UPDATE chat_rooms cr SET room_name = #{roomName}
WHERE cr.chat_room_id = #{chatRoomId}
  AND cr.chat = 'GROUP'
  AND EXISTS (
      SELECT 1
      FROM chat_room_members crm
      JOIN workspace_members wm ON crm.workspace_member_id = wm.workspace_member_id
      JOIN workspace_domains wd ON wm.workspace_id = wd.workspace_id

      WHERE crm.chat_room_id = cr.chat_room_id
        AND crm.workspace_member_id = cr.workspace_member_id
        AND wm.member_id = #{loginMemberId}
        AND wd.domain_key = #{domainKey}
        AND wd.active = 'Y'
        AND crm.status = 0
        AND wm.status = 0
  	)
